B.a1W=new A.fB("haydar_usta","KURNAZ EKSPERT\u0130Z USTASI","Haydar Usta","Sanayi Duayeni","\ud83d\udd27",B.O4,"\u201cPatron, garajdaki araban\u0131n \u015fasisi \u015f\xfcpheli duruyor. Normalde ekspertiz makinesi yar\u0131m saat s\xfcrer ama ben eski us\xfcl kula\u011f\u0131m\u0131 kaportaya dayar ci\u011ferini okurum. Bir \xe7\u0131ra\u011fa \xe7ay \u0131smarla, sana bu araba yat\u0131r\u0131ml\u0131k m\u0131 hurdal\u0131k m\u0131 hemen f\u0131s\u0131ldayay\u0131m!\u201d","Bekleme s\xfcresi olmadan an\u0131nda tam ekspertiz raporu & kusur tespiti.","\xc7AYA \xc7ORBAYA DESTEK (REKLAMI \u0130ZLE)","Hay\u0131r, Usta Dinlensin",B.El,null)
B.OI=new A.a9(983708,"MaterialIcons",null,!1)
B.a1U=new A.fB("zengin_sofor","KAPALI GARAJ \u0130PUCU","Kadir Beyin \u015eof\xf6r\xfc","Koleksiyoner Asistan\u0131","\ud83d\udd76\ufe0f",B.OI,"\u201cSelam usta. Patronum bu gece acilen yurt d\u0131\u015f\u0131na u\xe7uyor. Garajdaki koleksiyonluk arabay\u0131 piyasan\u0131n yar\u0131 fiyat\u0131na elden \xe7\u0131karacak. Konumu sana vermem i\xe7in bana ufak bir sponsorluk jesti yapman laz\u0131m...\u201d","Pazara %50 indirimli, y\xfcksek k\xe2r marjl\u0131 kelepir f\u0131rsat arac\u0131 eklenir.","KONUMU AL (REKLAMI \u0130ZLE)","Bana G\xfcven Vermedi",B.Em,null)
B.a1P=new A.fB("gece_boyaci","EKSPRES DETAILING","\xc7\u0131rak Taylan","Boya & Kaporta Kalfas\u0131","\u2728",B.t3,"\u201cUsta mesai bitti gidiyoruz ama \xe7\u0131raklara bir enerji i\xe7ece\u011fi \u0131smarlarsan gece vardiyas\u0131na kal\u0131r\u0131z! Arabaya sabaha kadar seramik kaplama ve pasta cila atar\u0131z. Yar\u0131n vitrinde iki kat\u0131 fiyata parlar!\u201d","Araca an\u0131nda %100 kusursuz boya/kaporta ve +%15 Vitrin Cazibesi (De\u011fer Art\u0131\u015f\u0131).","GECE VARD\u0130YASINI A\xc7 (REKLAMI \u0130ZLE)","Mesaiye Kalmas\u0131nlar",B.En,null)
B.a1R=new A.fB("kahve_molasi","PAZARLIK MASASI & KAHVE","H\xfcsn\xfc Bey","\u0130nat\xe7\u0131 M\xfc\u015fteri","\u2615",B.dv,"\u201cBu fiyat bana \xe7ok patron, ben masadan kalk\u0131yorum... Dur bakal\u0131m sekreter bir orta \u015fekerli T\xfcrk kahvesiyle ikram masas\u0131n\u0131 donat\u0131rsa masaya geri oturur, istedi\u011fin fiyata el s\u0131k\u0131\u015f\u0131r\u0131z!\u201d","M\xfc\u015fterinin direnci k\u0131r\u0131l\u0131r: Araca an\u0131nda liste fiyat\u0131n\u0131n %10 \xfczerine haz\u0131r sat\u0131\u015f f\u0131rsat\u0131.","\u0130KR\xc2M MASASINI DONAT (REKLAMI \u0130ZLE)","Normal Fiyata Raz\u0131y\u0131m",B.Eo,null)
B.NP=new A.a9(62996,"MaterialIcons",null,!1)
B.a1T=new A.fB("vlogger_ilan","V\u0130RAL \u0130LAN \u0130NCELEMES\u0130","Vlogger Berk","Oto Fenomeni","\ud83d\udcf9",B.NP,"\u201cSelam patron! Galerindeki \u015fu yatan arabayla ilgili YouTube kanal\u0131nda efsane bir reels patlatabilirim. Sponsorluk b\xfct\xe7emi kar\u015f\u0131la, yar\u0131m saate kap\u0131nda 3 tane haz\u0131r al\u0131c\u0131 s\u0131raya girsin!\u201d","\u0130landaki ara\xe7 i\xe7in an\u0131nda 3 adet haz\u0131r al\u0131c\u0131 teklifi ya\u011far ve h\u0131zla sat\u0131l\u0131r.","V\u0130RAL V\u0130DEOYU PATLAT (REKLAMI \u0130ZLE)","Gerek Yok, Kendi Sat\u0131l\u0131r",B.Ep,null)
B.a1S=new A.fB("sigorta_eksperi","S\u0130GORTA HASAR \u0130ST\u0130HBARATI","Eksper Melih","TRAMER Denet\xe7isi","\ud83d\udccb",B.jU,"\u201c\u0130haledeki ara\xe7lar\u0131n ger\xe7ek hasar dosyalar\u0131na ve k\xe2r analizlerine eri\u015fimim var. Bir \xe7ay\u0131m\u0131 tazelersen bir sonraki ihale i\xe7in +%20 net k\xe2r sa\u011flayan gizli eksper dosyas\u0131n\u0131 \xf6n\xfcne sereyim.\u201d","Galeri sermayene \u20ba30.000 analiz deste\u011fi ve ihale k\xe2r marj\u0131 bonusu aktar\u0131l\u0131r.","DOSYAYI \u0130NCELE (REKLAMI \u0130ZLE)","Riske Girerim",B.Eq,null)
B.a1Q=new A.fB("cikmaci_ibo","\xc7IKMA PAR\xc7A \u0130ND\u0130R\u0130M\u0130","\xc7\u0131kmac\u0131 \u0130bo","Yedek Par\xe7a Baronu","\ud83d\udd29",B.ew,"\u201cAlmanya\u2019dan t\u0131r dolusu orijinal s\u0131f\u0131r ayar\u0131nda yedek par\xe7a indirdim! \xc7\u0131raklara ufak bir destek atarsan at\xf6lye masraflar\u0131n i\xe7in sana \u20ba35.000 de\u011ferinde par\xe7a kredisi hibe ediyorum!\u201d","At\xf6lye tamirat ve yedek par\xe7a kasana \u20ba35.000 nakit hibe eklenir.","PAR\xc7A KRED\u0130S\u0130N\u0130 AL (REKLAMI \u0130ZLE)","Orijinal Par\xe7adan \u015ea\u015fmam",B.Er,null)
B.a1V=new A.fB("cekici_remzi","\xc7EK\u0130C\u0130 LOJ\u0130ST\u0130K DESTE\u011e\u0130","\xc7ekici Remzi","A\u011f\u0131r Vas\u0131ta Operat\xf6r\xfc","\ud83d\ude9a",B.nt,"\u201cHurdal\u0131ktan veya sanayiden \xe7ekece\u011fin ara\xe7lar i\xe7in bo\u015f d\xf6n\xfcyordum. Bana bir \xe7orba paras\u0131 b\u0131rak, bir sonraki nakliye operasyonunu ve \u20ba25.000 lojistik bedelini \u015firkete yazay\u0131m!\u201d","Lojistik ve nakliye fonuna \u20ba25.000 hibe kredisi tan\u0131mlan\u0131r.","\xc7EK\u0130C\u0130Y\u0130 Y\xd6NLEND\u0130R (REKLAMI \u0130ZLE)","Kendi \xc7ekicimiz Var",B.Es,null)
